export function getStreet(slug: string): TbilisiStreet | undefined {
  return STREETS.find((s) => s.slug === slug)
}

export function streetsOfDistrict(districtSlug: string): TbilisiStreet[] {
  return STREETS.filter((s) => s.district === districtSlug).sort((a, b) => a.ka.localeCompare(b.ka, 'ka'))
}

const STREET_SUFFIXES = new Set(['გამზირი', 'ქუჩა', 'ხეივანი', 'სანაპირო', 'გზატკეცილი', 'მოედანი', 'აღმართი', 'დაღმართი', 'შესახვევი', 'გასასვლელი', 'ჩიხი', 'გზა', 'I', 'II', 'III', 'IV', 'V'])

const STREET_TYPES = [
  'გამზირი', 'ქუჩა', 'ხეივანი', 'სანაპირო', 'გზატკეცილი', 'მოედანი', 'შესახვევი', 'გასასვლელი', 'ჩიხი',
] as const

/** Abbrev + case fold so „ჭავჭავაძის გამზ." hits catalog „ილია ჭავჭავაძის გამზირი". */
function normStreetKa(s: string): string {
  return s
    .trim()
    .toLowerCase()
    .replace(/გამზ\.?/gu, 'გამზირი')
    .replace(/(?:^|\s)ქ\.?(?=\s|$)/gu, ' ქუჩა')
    .replace(/\s+/g, ' ')
    .trim()
}

export function streetCore(ka: string): string {
  const words = ka.split(/\s+/).filter((w) => !STREET_SUFFIXES.has(w))
  return words[words.length - 1] ?? ka
}

/**
 * Catalog ubani (ka) for a street label — STREETS.district from OSM spatial join.
 * Short forms OK: „ჭავჭავაძის გამზირი" → ვაკე. Ambiguous bare surname → no guess.
 */
export function districtKaForStreet(raw: string): string | undefined {
  const needle = normStreetKa(raw)
  if (needle.length < 4) return undefined

  let best: TbilisiStreet | undefined
  let bestScore = 0
  const needleType = STREET_TYPES.find((t) => needle.includes(t))

  for (const s of STREETS) {
    if (!s.district) continue
    const ka = normStreetKa(s.ka)
    let score = 0
    if (ka === needle) score = 1000 + ka.length
    else if (needle.length >= 8 && ka.endsWith(needle)) score = 500 + needle.length
    else if (ka.length >= 8 && needle.endsWith(ka)) score = 400 + ka.length
    else {
      const core = streetCore(s.ka).toLowerCase()
      if (core.length < 5 || !needle.includes(core)) continue
      const streetType = STREET_TYPES.find((t) => ka.includes(t))
      if (needleType && streetType && needleType !== streetType) continue
      if (!needleType) continue
      score = 100 + core.length
    }
    if (score > bestScore) {
      bestScore = score
      best = s
    }
  }
  return best?.district ? canonicalizeDistrict(best.district) || undefined : undefined
}

function includesWord(hay: string, needle: string): boolean {
  let i = hay.indexOf(needle)
  while (i !== -1) {
    const before = hay[i - 1] ?? ''
    const after = hay[i + needle.length] ?? ''
    if (!/[ა-ჿ]/.test(before) && !/[ა-ჿ]/.test(after)) return true
    i = hay.indexOf(needle, i + 1)
  }
  return false
}

function coreVariants(core: string): string[] {
  const out = new Set([core])
  const chars = [...core]
  chars.forEach((c, i) => {
    if (c !== 'ჭ' && c !== 'ჩ') return
    for (const v of [...out]) {
      out.add(v.slice(0, i) + (v[i] === 'ჭ' ? 'ჩ' : 'ჭ') + v.slice(i + 1))
    }
  })
  return [...out]
}

export function listingsOfStreet(street: TbilisiStreet): Listing[] {
  const variants = coreVariants(streetCore(street.ka))
  return LISTINGS.filter(
    (l) => l.city === 'თბილისი' && variants.some((v) => includesWord(l.address, v)),
  )
}

export function streetLocative(ka: string): string {
  const words = ka.split(/\s+/)
  const last = words[words.length - 1]!
  const loc = last.endsWith('ი') ? `${last.slice(0, -1)}ზე` : `${last}ზე`
  return [...words.slice(0, -1), loc].join(' ')
}
